(()=>{'use strict';
 const files=[['纳爱斯','planning-nice.pdf'],['赤尾','planning-redtail.pdf'],['打工人摸鱼','planning-fish.pdf']];
 const project=projects.find(p=>p.id==='planning'),original=project.material;
 project.material=()=>original()+`<section class="planning-reader" aria-label="完整策划案"><h3>完整策划案</h3><div class="pdf-tabs" role="tablist" aria-label="选择完整策划案">${files.map(([name],i)=>`<button type="button" role="tab" data-pdf="${i}" aria-selected="${i===0}">${name}</button>`).join('')}</div><div class="pdf-tools"><button type="button" data-prev disabled aria-label="上一页">上一页</button><label>第 <input data-page type="number" min="1" value="1" aria-label="跳转页码" disabled> / <span data-total>—</span> 页</label><button type="button" data-next disabled aria-label="下一页">下一页</button><select data-zoom aria-label="阅读缩放" disabled><option value="1">适合宽度</option><option value="1.25">放大 125%</option><option value="1.5">放大 150%</option><option value="2">放大 200%</option></select><a class="pdf-open" href="documents/planning-nice.pdf" target="_blank" rel="noopener">打开完整 PDF ↗</a></div><p class="pdf-status" role="status" aria-live="polite">点击阅读后加载完整原稿。</p><div class="pdf-window" role="tabpanel" aria-label="纳爱斯完整策划案"><button type="button" class="pdf-start">阅读完整策划案</button><canvas hidden aria-label="PDF 当前页"></canvas></div></section>`;
 async function originalPDF(index,signal){const base='documents/'+files[index][1].replace('.pdf','')+'/';const response=await fetch(base+'manifest.json',{signal});if(!response.ok)throw Error('PDF unavailable');const manifest=await response.json();const chunks=await Promise.all(manifest.chunks.map(async file=>{const r=await fetch(base+file,{signal});if(!r.ok)throw Error('PDF unavailable');return new Uint8Array(await r.arrayBuffer());}));const data=new Uint8Array(manifest.bytes);let offset=0;for(const part of chunks){data.set(part,offset);offset+=part.length;}if(offset!==manifest.bytes)throw Error('Incomplete PDF');return data;}
 let library,cleanup=()=>{};const panel=document.querySelector('#detail-panel');
 const watch=new MutationObserver(()=>{const root=panel.querySelector('.planning-reader');if(root&&!root.dataset.ready){cleanup();cleanup=mount(root);}else if(!root){cleanup();cleanup=()=>{};}});watch.observe(panel,{childList:true});
 function mount(root){root.dataset.ready='true';const $=s=>root.querySelector(s),canvas=$('canvas'),box=$('.pdf-window'),status=$('.pdf-status');let selected=0,page=1,zoom=1,doc=null,loadTask=null,renderTask=null,seq=0,disposed=false,timer,controller=null,blobURL=null;const urls=[];
 function state(busy){$('[data-prev]').disabled=busy||!doc||page<=1;$('[data-next]').disabled=busy||!doc||page>=doc.numPages;$('[data-page]').disabled=busy||!doc;$('[data-zoom]').disabled=busy||!doc;$('[data-page]').value=page;}
 async function draw(){if(!doc||disposed)return;const ticket=++seq;renderTask?.cancel();state(true);try{const pdfPage=await doc.getPage(page);if(ticket!==seq||disposed)return;const v=pdfPage.getViewport({scale:1}),available=box.clientWidth-(innerWidth<=520?12:24),view=pdfPage.getViewport({scale:available/v.width*zoom}),dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.ceil(view.width*dpr);canvas.height=Math.ceil(view.height*dpr);canvas.style.width=view.width+'px';canvas.style.height=view.height+'px';canvas.hidden=false;renderTask=pdfPage.render({canvasContext:canvas.getContext('2d'),viewport:view,transform:[dpr,0,0,dpr,0,0]});await renderTask.promise;if(ticket!==seq||disposed)return;status.textContent=files[selected][0]+' · 第 '+page+' / '+doc.numPages+' 页';canvas.setAttribute('aria-label',files[selected][0]+' 第 '+page+' 页');box.scrollTop=0;state(false);}catch(e){if(e.name==='RenderingCancelledException'||disposed)return;status.textContent='此页暂时无法显示，可使用“打开完整 PDF”阅读。';state(false);}}
 async function load(index){const ticket=++seq;controller?.abort();controller=new AbortController();selected=index;page=1;zoom=1;$('[data-zoom]').value='1';doc=null;renderTask?.cancel();if(loadTask){await loadTask.destroy().catch(()=>{});loadTask=null;}if(ticket!==seq||disposed)return;root.querySelectorAll('[data-pdf]').forEach((e,i)=>e.setAttribute('aria-selected',String(i===index)));$('.pdf-open').href='#';blobURL=null;box.setAttribute('aria-label',files[index][0]+'完整策划案');$('[data-total]').textContent='—';$('.pdf-start').hidden=true;canvas.hidden=true;status.textContent='正在加载'+files[index][0]+'完整策划案…';state(true);
 try{library??=import('./vendor/pdfjs/pdf.min.mjs');const pdf=await library;if(ticket!==seq||disposed)return;pdf.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/pdf.worker.min.mjs',document.baseURI).href;const bytes=await originalPDF(index,controller.signal);if(ticket!==seq||disposed)return;blobURL=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));urls.push(blobURL);$('.pdf-open').href=blobURL;loadTask=pdf.getDocument({data:bytes,cMapUrl:'vendor/pdfjs/cmaps/',cMapPacked:true,standardFontDataUrl:'vendor/pdfjs/standard_fonts/',isEvalSupported:false,disableAutoFetch:true,disableStream:true});const loaded=await loadTask.promise;if(ticket!==seq||disposed)return;doc=loaded;$('[data-total]').textContent=doc.numPages;$('[data-page]').max=doc.numPages;await draw();}catch(e){if(ticket!==seq||disposed)return;status.textContent='加载未完成，可重试或打开完整 PDF。';$('.pdf-start').hidden=false;state(false);}}
 $('.pdf-open').href='#';$('.pdf-open').onclick=async e=>{if(blobURL)return;e.preventDefault();const win=window.open('about:blank','_blank');if(win)win.opener=null;try{const data=await originalPDF(selected);const url=URL.createObjectURL(new Blob([data],{type:'application/pdf'}));urls.push(url);if(win)win.location.replace(url);else{blobURL=url;$('.pdf-open').href=url;status.textContent='完整 PDF 已就绪，再次点击即可打开。';}}catch{win?.close();status.textContent='完整 PDF 加载失败，请重试。';}};
 $('.pdf-start').onclick=()=>load(selected);root.querySelectorAll('[data-pdf]').forEach((e,i)=>e.onclick=()=>load(i));$('[data-prev]').onclick=()=>{page--;draw();};$('[data-next]').onclick=()=>{page++;draw();};$('[data-page]').onchange=e=>{page=Math.max(1,Math.min(doc.numPages,Math.trunc(Number(e.target.value))||1));draw();};$('[data-zoom]').onchange=e=>{zoom=Number(e.target.value);draw();};
 let lastWidth=box.clientWidth;const observer=new ResizeObserver(()=>{if(box.clientWidth===lastWidth)return;lastWidth=box.clientWidth;clearTimeout(timer);timer=setTimeout(()=>draw(),150);});observer.observe(box);
 return ()=>{disposed=true;seq++;controller?.abort();setTimeout(()=>urls.forEach(url=>URL.revokeObjectURL(url)),60000);clearTimeout(timer);observer.disconnect();renderTask?.cancel();loadTask?.destroy().catch(()=>{});};
 }
})();
